import{_ as p,a0 as i,w as l,s as n,ao as d,I as r,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"成為一名軟件開發者你應該學習哪種語言？ | LCTT x X-CMD","titleTemplate":false,"description":"成為一名軟件開發者你應該學習哪種語言？ | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"成為一名軟件開發者你應該學習哪種語言？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"成為一名軟件開發者你應該學習哪種語言？ | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170616 Do you have what it takes to be a software developer","title":"成為一名軟件開發者你應該學習哪種語言？","tag":"201707","desc":""},"relativePath":"201707/20170616 Do you have what it takes to be a software developer.md","filePath":"[post].md"}'),u={name:"201707/20170616 Do you have what it takes to be a software developer.md"};function w(f,t,v,m,T,b){const a=i("Link");return l(),n("div",null,[t[13]||(t[13]=d('<h1 id="成為一名軟件開發者你應該學習哪種語言" tabindex="-1">成為一名軟件開發者你應該學習哪種語言？ <a class="header-anchor" href="#成為一名軟件開發者你應該學習哪種語言" aria-label="Permalink to “成為一名軟件開發者你應該學習哪種語言？”">​</a></h1><p><img src="https://www.linuxcareer.com/images/software_developer_skills.jpg" alt=""></p><p>應用程序的領域在不斷發展。底層的 Linux 做了很多工作，而且還在繼續，但是在過去幾年裏，應用程序領域開始增長。在這種情況下，開發人員使用哪種語言構建這些應用程序？簡而言之，要看情況，我知道這個説法沒啥稀奇的。但是，通過我們擁有的數據，我們可以確定哪些語言領先。</p><p>站在山頂的語言是 Java。它已經出現在開源軟件領域 15 年以上，但它並不是一直在頂峯。在早期，我們沒有看到那麼多對 java 開發者感興趣的，但現在情況已經改變了。它是目前應用領域的權威領導者。雖然這個數字在過去六個季度沒有明顯增長，但其整體數量卻令人印象深刻。平均而言，關注於開源軟件的公司發佈的職位中有超過 1/3 的職位要求 Java 技能。這對幾年前沒有在榜單上出現的語言而言是一個非凡的成就。而且，由於它在 Android 中的大量使用，未來這個數字進一步增加也並不奇怪。</p><p>在應用程序領域中使用的另一種語言是 C++。雖然它的數量不能與 Java 競爭，但它仍然在這個領域佔據了很大的市場份額。而且每 3 個招聘中有一個要求 Java，C++ 則是每 4 箇中有一個要求它。與 Java 非常類似，其數量在過去六個季度中保持相對穩定。C++ 一直被大量使用，即使 Java 已經取代它，它仍然是一種高度相關的語言。</p><p>進入到網絡應用領域，多年來一直在城頭變幻大王旗。在早期，大多數 Web 程序毫無疑問地選擇使用 PHP 開發。正如之前關於腳本的文章所討論的，這幾年來已經發生了變化。在過去幾年中，PHP 的使用似乎有所惡化。在過去一年半的時間裏，已經急劇下降了 30％ 以上。這是一個令人震驚的數字，只有時間才能告訴我們趨勢是否持續。</p><p>最初打破 PHP 領導地位的是 Ruby on Rails。多年來，我看到公司們和開發者們進行了這一轉型。Ruby on Rails 經歷了一段時間，在這個時期它是這個領域的首選語言。然而，從我們收集的數字來看，它的光澤似乎已經失去了一點。雖然沒有像 PHP 這樣的衰退，但其數量一直保持相對平穩，它曾經有過的增長似乎停滯不前。</p><p>目前在網絡應用程序領域的王者似乎是 Javascript。它獲得了最大的總數。雖然它的數量保持平坦，這很像 Ruby on Rails，但它已經吸引了更多的觀眾。平均來説，過去六個季度，公司在分析的 10,000 份工作清單中有 1,500 份需要 Javascript 技能。這比 PHP 或 Ruby on Rails 多了 70％。</p><p>隨着 PHP 的衰落以及 Ruby on Rails 和 Javascript 停滯不前，是誰在 Web 程序領域保持增長呢？這個羣體的突出者似乎是 Golang。它在 2007 年由 Google 內的幾位開發人員創建，似乎這種語言開始獲得更廣泛的受眾羣體。雖然與我們討論的其它三個的總數相比不多，但看起來這一年半以來增長了 50％。如果這種趨勢繼續下去，那將是非常有趣的。在我看來，我預計我們會繼續看到 Golang 擠佔 其它三個的羣體份額。</p><p>如往常一樣，我們會監測這些語言的各種前進方向，以觀察市場趨勢。而且，榜單的任何新進入者都會被密切關注。這是一個令人興奮和動態的發展領域。一個會提供隨時間不斷變化的結果。</p><hr>',11)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(a,{href:"https://www.linuxcareer.com/do-you-have-what-it-takes-to-be-a-software-developer"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.linuxcareer.com/do-you-have-what-it-takes-to-be-a-software-developer",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),o(a,{href:"https://www.linuxcareer.com/do-you-have-what-it-takes-to-be-a-software-developer"},{default:s(()=>[...t[2]||(t[2]=[e("Brent Marinaccio",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),o(a,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const _=p(u,[["render",w]]);export{P as __pageData,_ as default};
